<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login - Ma'had Aly</title><link rel="stylesheet" href="assets/style.css"><style>.password-field{position:relative}.password-field input{padding-right:52px;box-sizing:border-box}.password-field .password-toggle{position:absolute;right:6px;top:50%;transform:translateY(-50%);display:grid;place-items:center;width:44px;height:44px;padding:10px;margin:0;background:transparent;color:#174358;border:0;border-radius:8px;cursor:pointer}.password-toggle:focus-visible{outline:2px solid #087d6c;outline-offset:1px}.password-toggle svg{width:24px;height:24px}.password-toggle[aria-pressed="false"] .eye-slash{display:none}</style></head><body><main class="login card"><h1>Ma'had Aly Luqmanul Hakim</h1><p>Masuk ke Sistem Informasi Manajemen</p><?php if (!empty($_SESSION['flash'])): ?><p class="error"><?=esc($_SESSION['flash'])?></p><?php unset($_SESSION['flash']); endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><label for="username">Username</label><input id="username" name="username" autocomplete="username" required><label for="password">Password</label><div class="password-field"><input id="password" name="password" type="password" autocomplete="current-password" required><button type="button" class="password-toggle" aria-label="Tampilkan password" title="Tampilkan password" aria-controls="password" aria-pressed="false" onclick="const p=document.getElementById('password');const show=p.type==='password';p.type=show?'text':'password';this.setAttribute('aria-pressed',String(show));this.setAttribute('aria-label',show?'Sembunyikan password':'Tampilkan password');this.title=this.getAttribute('aria-label')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path class="eye-slash" d="m3 3 18 18"/></svg></button></div><button name="action" value="login">Masuk</button></form></main></body></html>
